<script setup lang="ts">import {onMounted,ref} from 'vue';import {request} from '../../api/http';const items=ref<any[]>([]),error=ref('');onMounted(async()=>{try{items.value=(await request<any>({url:'/public/doctors',data:{page:1,pageSize:50}})).data.records;}catch{error.value='加载失败';}});function detail(id:string){uni.navigateTo({url:`/pages/doctor-detail/index?id=${id}`});}</script><template><view class="page"><view v-if="error">{{error}}</view><view v-else-if="!items.length">暂无已发布医生</view><view v-for="item in items" :key="item.id" class="card" @click="detail(item.id)"><text class="name">{{item.name}} {{item.title}}</text><text>{{item.departments.map((x:any)=>x.name).join('、')}}</text><text>{{item.specialties.map((x:any)=>x.name).join('、')||item.specialtySummary}}</text></view></view></template><style scoped>.page{padding:28rpx}.card{display:flex;flex-direction:column;gap:12rpx;padding:28rpx;background:#fff;border-radius:16rpx;margin-bottom:18rpx;color:#64748b}.name{font-size:34rpx;color:#17324d;font-weight:700}</style>
